/**
 * @file audio_features.h
 * @brief On-device 29-feature extractor -- bit-faithful C mirror of
 *        ml_model/extract_features.py (the PC-side trainer front end).
 *
 * Pipeline per 1 s window (16000 samples @ 16 kHz mono int16):
 *   frames 512 / hop 256, Hann window -> 512-pt FFT -> power spectrum
 *   -> 40-mel filterbank -> natural log -> DCT-II -> 13 MFCCs
 *   -> aggregate mean/std of each MFCC (26) + log-energy mean/std (2)
 *      + mean zero-crossing rate (1) = 29 features.
 *
 * The FFT/mel/DCT coefficient tables live in audio_features_tables.h,
 * GENERATED by ml_model/gen_c_tables.py from the exact Python matrices so
 * the C and PC extractors are numerically identical (parity is enforced by
 * test/test_features with golden vectors).
 *
 * Pure C (stdint/math only) so the same file compiles on the board and in
 * the host Unity suite (test/test_features includes it directly).
 */
#ifndef AUDIO_FEATURES_H_
#define AUDIO_FEATURES_H_

#include <stdint.h>

/* Matches the trainer: 1 s windows at exactly 16 kHz (the device ring
 * delivers 16039 samples/s; the last 39 are dropped so the feature
 * statistics match training exactly). */
#define AUDIO_FEAT_WINDOW_SAMPLES 16000u
#define AUDIO_FEAT_COUNT          29u

/* Precompute FFT twiddle factors. Call once before compute(). */
void audio_features_init(void);

/**
 * Compute the 29-feature vector for one window.
 * @param window raw mono int16 samples (AUDIO_FEAT_WINDOW_SAMPLES valid)
 * @param n      number of samples in window (must be AUDIO_FEAT_WINDOW_SAMPLES)
 * @param out    caller-provided float[AUDIO_FEAT_COUNT]
 */
void audio_features_compute(const int16_t *window, uint32_t n, float *out);

#endif /* AUDIO_FEATURES_H_ */
